**`main.go`**

```go
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"math/rand"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/InfluxCommunity/influxdb3-go/v2/influxdb3"
	"github.com/influxdata/line-protocol/v2/lineprotocol"
	"github.com/joho/godotenv"
)

func main() {
	_ = godotenv.Load()

	host := strings.TrimRight(mustEnv("INFLUXDB_HOST"), "/")
	token := mustEnv("INFLUXDB_TOKEN")
	database := mustEnv("INFLUXDB_DATABASE")

	// InfluxDB 3 silently auto-creates a database on first write, so a typo in
	// INFLUXDB_DATABASE would "succeed" into a new, wrong database. Check first.
	if err := requireDatabase(host, token, database); err != nil {
		log.Fatal(err)
	}

	client, err := influxdb3.New(influxdb3.ClientConfig{
		Host:     host,
		Token:    token,
		Database: database,
	})
	if err != nil {
		log.Fatalf("client init: %v", err)
	}
	defer client.Close()

	ctx := context.Background()
	now := time.Now().Truncate(time.Second)

	sensors := []struct{ id, room string }{
		{"sensor-001", "kitchen"},
		{"sensor-002", "living-room"},
		{"sensor-003", "garage"},
	}

	// 10 readings per sensor, one per minute over the last 10 minutes.
	var points []*influxdb3.Point
	for _, s := range sensors {
		for i := 0; i < 10; i++ {
			ts := now.Add(-time.Duration(10-i) * time.Minute)
			points = append(points,
				influxdb3.NewPointWithMeasurement("sensor_readings").
					SetTag("sensor_id", s.id).
					SetTag("room", s.room).
					SetField("temperature", round1(20+rand.Float64()*5)).
					SetField("humidity", round1(40+rand.Float64()*15)).
					SetField("battery", int64(100-i)).
					SetTimestamp(ts))
		}
	}

	fmt.Printf("==> Writing %d points to %q on %s\n", len(points), database, host)
	if err := client.WritePoints(ctx, points, influxdb3.WithPrecision(lineprotocol.Second)); err != nil {
		log.Fatalf("write: %v", err)
	}

	fmt.Println("==> Reading back the latest rows")
	iter, err := client.Query(ctx,
		"SELECT * FROM sensor_readings WHERE time >= now() - INTERVAL '1 hour' ORDER BY time DESC LIMIT 5")
	if err != nil {
		log.Fatalf("query: %v", err)
	}
	for iter.Next() {
		fmt.Println(iter.Value())
	}
	if err := iter.Err(); err != nil {
		log.Fatalf("iterate: %v", err)
	}
	fmt.Println("==> Done")
}

// requireDatabase lists databases via /api/v3/configure/database and fails if
// the target isn't there.
func requireDatabase(host, token, database string) error {
	req, err := http.NewRequest(http.MethodGet, host+"/api/v3/configure/database?format=json", nil)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+token)

	resp, err := (&http.Client{Timeout: 10 * time.Second}).Do(req)
	if err != nil {
		return fmt.Errorf("cannot reach InfluxDB at %s: %w", host, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("listing databases failed: HTTP %d (check INFLUXDB_TOKEN)", resp.StatusCode)
	}

	var rows []map[string]string
	if err := json.NewDecoder(resp.Body).Decode(&rows); err != nil {
		return fmt.Errorf("decode database list: %w", err)
	}
	var names []string
	for _, r := range rows {
		if r["iox::database"] == database {
			return nil
		}
		names = append(names, r["iox::database"])
	}
	return fmt.Errorf("database %q not found (existing: %v). Create it with:\n  influxdb3 create database %s --token <admin-token>",
		database, names, database)
}

func mustEnv(k string) string {
	v := os.Getenv(k)
	if v == "" {
		log.Fatalf("missing env var %s", k)
	}
	return v
}

func round1(f float64) float64 { return float64(int(f*10+0.5)) / 10 }
```

**Setup** (skip any steps you already did for the Python script):

1. **Create a token.** Use the one Core printed at first start, or create one with `influxdb3 create token --admin`. Core only has admin tokens, so it's best to create a separate named one for this app.
2. **Create the database:**
   ```bash
   influxdb3 create database sensor_data --token <admin-token>
   ```
3. **Keep the token out of git:**
   ```bash
   grep -qx '.env' .gitignore || echo '.env' >> .gitignore
   ```
   Commit a `.env.example` with placeholder values, and put the real values in `.env`:
   ```
   INFLUXDB_HOST=http://localhost:8181
   INFLUXDB_TOKEN=<your-token>
   INFLUXDB_DATABASE=sensor_data
   ```
4. **Install the dependencies and run it:**
