import 'dotenv/config';
import { InfluxDBClient } from '@influxdata/influxdb3-client';

const REQUIRED = ['INFLUXDB_HOST', 'INFLUXDB_TOKEN', 'INFLUXDB_DATABASE'];

export function loadConfig() {
  const missing = REQUIRED.filter((name) => !process.env[name]);
  if (missing.length > 0) {
    throw new Error(`Missing env vars: ${missing.join(', ')}. Copy .env.example to .env and fill it in.`);
  }
  return {
    host: process.env.INFLUXDB_HOST,
    token: process.env.INFLUXDB_TOKEN,
    database: process.env.INFLUXDB_DATABASE,
  };
}

// Cloud Serverless has no /api/v3 database-list endpoint, so confirm the bucket
// exists (and the token can read it) with a cheap query before any writes.
export async function verifyDatabase(client, database) {
  try {
    const rows = client.query(
      'SELECT table_name FROM information_schema.tables LIMIT 1',
      database,
      { type: 'sql' }
    );
    for await (const _ of rows) break;
  } catch (err) {
    throw new Error(
      `Cannot query bucket "${database}". Check that it exists in Cloud Serverless ` +
        `and that INFLUXDB_TOKEN has read access to it. Cause: ${err.message}`
    );
  }
}

export async function connect() {
  const { host, token, database } = loadConfig();
  const client = new InfluxDBClient({ host, token, database });
  await verifyDatabase(client, database);
  return { client, database };
}
