}

// Fails fast if the bucket doesn't exist or the token can't read it, so a
// typo in INFLUXDB_DATABASE surfaces at startup instead of on the first write.
export async function assertDatabaseReachable(client, database) {
  try {
    const rows = client.query(
      'SELECT table_name FROM information_schema.tables LIMIT 1',
      database,
      { type: 'sql' }
    );
    for await (const _row of rows) break;
  } catch (err) {
    throw new Error(
      `Cannot query bucket "${database}". Check that INFLUXDB_DATABASE is spelled correctly, ` +
        `the bucket exists, and INFLUXDB_TOKEN has read access to it. Cause: ${err.message}`
    );
  }
}

export async function createClient() {
  const { host, token, database } = loadConfig();
  const client = new InfluxDBClient({ host, token, database });
  await assertDatabaseReachable(client, database);
  return { client, database };
}
```

