```javascript
import 'dotenv/config';
import { InfluxDBClient } from '@influxdata/influxdb3-client';

const host = process.env.INFLUXDB_HOST;
const token = process.env.INFLUXDB_TOKEN;
const database = process.env.INFLUXDB_DATABASE;

if (!host || !token || !database) {
  throw new Error('INFLUXDB_HOST, INFLUXDB_TOKEN, and INFLUXDB_DATABASE are required');
}

// Usage: node page-sensors.js 2026-09-01T00:00:00Z 2026-09-28T00:00:00Z
const [startArg, endArg] = process.argv.slice(2);
if (!startArg || !endArg) throw new Error('Usage: node page-sensors.js <startISO> <endISO>');
const rangeStart = new Date(startArg);
const rangeEnd = new Date(endArg);

// Tune so one window holds a manageable number of rows (e.g. 100k–1M).
const WINDOW_MS = 60 * 60 * 1000; // 1 hour

// Fail fast if the database name is wrong, instead of paging through nothing.
async function assertDatabaseExists() {
  const res = await fetch(`${host.replace(/\/$/, '')}/api/v3/configure/database?format=json`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(`Listing databases failed: HTTP ${res.status}`);
  const dbs = (await res.json()).map((d) => d['iox::database'] ?? d.name ?? d);
  if (!dbs.includes(database)) {
    throw new Error(`Database "${database}" not found. Available: ${dbs.join(', ')}`);
  }
}

const client = new InfluxDBClient({ host, token, database });

const sql = `
  SELECT *
  FROM sensor
  WHERE time >= CAST($start AS TIMESTAMP)
    AND time <  CAST($end   AS TIMESTAMP)
  ORDER BY time
`;

async function* pageByTime() {
  for (let t = rangeStart.getTime(); t < rangeEnd.getTime(); t += WINDOW_MS) {
    const start = new Date(t).toISOString();
    const end = new Date(Math.min(t + WINDOW_MS, rangeEnd.getTime())).toISOString();
    const rows = client.query(sql, database, { type: 'sql', params: { start, end } });
    yield { start, end, rows };
  }
}

try {
  await assertDatabaseExists();
  let total = 0;
  for await (const { start, end, rows } of pageByTime()) {
    let count = 0;
    for await (const row of rows) {
      // process(row) — e.g. write to a file, transform, forward elsewhere
      count++;
    }
    total += count;
    console.log(`${start} → ${end}: ${count} rows (total ${total})`);
  }
} finally {
  await client.close();
}
```

## Notes

- **Choosing the window size:** at a steady ~1,000 rows/s, a 1-hour window is about 3.6M rows. If your write rate is uneven, you can size windows from `SELECT DATE_BIN(INTERVAL '1 hour', time) AS h, COUNT(*) FROM sensor WHERE ... GROUP BY h`.
- **Core-specific benefit:** Core limits how many Parquet files a single query can scan, so one query over a very large time range can fail. Querying one window at a time stays under that limit. Check the Core docs for your version's limit instead of relying on a fixed number.
- **Resuming after a crash:** save the last finished window's `end` and restart from it. Each window's results are complete and don't depend on the others.
- **Faster runs:** windows don't depend on each other, so you can fetch 2–4 of them at once (for example with `Promise.all` over small batches).
- **Only use `LIMIT/OFFSET`** when the result isn't ordered by time, and expect later pages to be slow.
- **Timestamp values:** for a numeric timestamp in each row, select `date_part('epoch', time) AS ts` explicitly.

Use **time windows**, not `LIMIT/OFFSET`. Query one fixed time range at a time, stream the rows in that window, then move to the next range. The JS client reads results over Arrow Flight and gives them to you as an async iterator, so memory stays flat. Because each window is independent, a crashed job can resume from the last completed window.

Don't use these two approaches for 10M rows:
- **`LIMIT n OFFSET m`**: the server still has to scan and discard all `m` skipped rows. Each page gets slower, and the last pages are very slow.
- **Time window plus `LIMIT`**: if a window has more rows than the limit, the extra rows are silently dropped. Pick a window size and stream everything in it instead.

