  for await (const { start, end, rows } of pageSensorData()) {
    let n = 0;
    for await (const row of rows) {
      // process(row) — write to file, transform, forward, etc.
      n++;
    }
    total += n;
    // Persist `end` here as a checkpoint if you want resumability.
    console.log(`${start} → ${end}: ${n} rows (total ${total})`);
  }
} finally {
  await client.close();
