```csharp
using System.Diagnostics;
using System.Net;
using System.Net.Http.Headers;
using System.Text.Json;
using DotNetEnv;
using InfluxDB3.Client;
using InfluxDB3.Client.Write;

const int TotalPoints = 1_000_000;
const int BatchSize   = 10_000;  // documented starting range: 1,000–10,000 per write
const int Concurrency = 4;       // batches in flight at once
const int Hosts       = 100;     // 100 hosts × 10,000 seconds = 1M unique (tags, timestamp) pairs
const int MaxRetries  = 5;

Env.Load();
var host     = Require("INFLUXDB_HOST");
var token    = Require("INFLUXDB_TOKEN");
var database = Require("INFLUXDB_DATABASE");

// InfluxDB 3 silently auto-creates a database on first write, so a typo
// in INFLUXDB_DATABASE would "succeed" into the wrong place. Check first.
await EnsureDatabaseExists(host, token, database);

using var client = new InfluxDBClient(host: host, token: token, database: database);

// Second precision: one point per series per second, so no overwrites.
var start = DateTime.UtcNow.AddSeconds(-(TotalPoints / Hosts));
start = new DateTime(start.Ticks - start.Ticks % TimeSpan.TicksPerSecond, DateTimeKind.Utc);

long written = 0;
var sw = Stopwatch.StartNew();

await Parallel.ForEachAsync(
    Enumerable.Range(0, TotalPoints / BatchSize),
    new ParallelOptions { MaxDegreeOfParallelism = Concurrency },
    async (batchNo, ct) =>
    {
        var batch = BuildBatch(batchNo, start);   // built lazily; never holds all 1M points
        await WriteWithRetry(client, batch, batchNo, ct);
        var total = Interlocked.Add(ref written, batch.Count);
        if (total % 100_000 == 0)
            Console.WriteLine($"==> {total:N0} points ({total / sw.Elapsed.TotalSeconds:N0} pts/s)");
    });

Console.WriteLine($"==> Done: {written:N0} points in {sw.Elapsed.TotalSeconds:N1}s");

static List<PointData> BuildBatch(int batchNo, DateTime start)
{
    var batch = new List<PointData>(BatchSize);
    for (var i = batchNo * BatchSize; i < (batchNo + 1) * BatchSize; i++)
    {
        var hostId = i % Hosts;
        var second = i / Hosts;
        batch.Add(PointData.Measurement("sensor")
            .SetTag("host", $"server{hostId:D3}")
            .SetTag("region", hostId < Hosts / 2 ? "us-west" : "us-east")
            .SetField("temperature", 20.0 + Random.Shared.NextDouble() * 10)
            .SetField("humidity", 40.0 + Random.Shared.NextDouble() * 20)
            .SetTimestamp(start.AddSeconds(second)));
    }
    return batch;
}

static async Task WriteWithRetry(InfluxDBClient client, List<PointData> batch, int batchNo, CancellationToken ct)
{
    for (var attempt = 0; ; attempt++)
    {
        try
        {
            await client.WritePointsAsync(batch, precision: WritePrecision.S, cancellationToken: ct);
            return;
        }
        catch (Exception e) when (attempt < MaxRetries && IsRetriable(e))
        {
            // Exponential backoff with jitter, capped at 30s.
            var ms = Math.Min(30_000, 500 * Math.Pow(2, attempt)) * (0.5 + Random.Shared.NextDouble());
            Console.Error.WriteLine($"batch {batchNo}: attempt {attempt + 1} failed ({e.Message}); retrying in {ms:N0}ms");
            await Task.Delay(TimeSpan.FromMilliseconds(ms), ct);
        }
        // 400/401/403/404/413 are not retried: they propagate and stop the run.
    }
}

static bool IsRetriable(Exception e) => e switch
{
    InfluxDBApiException api => api.StatusCode == HttpStatusCode.TooManyRequests || (int)api.StatusCode >= 500,
    HttpRequestException     => true,   // connection refused/reset
    _                        => false,
};

static async Task EnsureDatabaseExists(string host, string token, string database)
{
    using var http = new HttpClient { BaseAddress = new Uri(host) };
    using var req = new HttpRequestMessage(HttpMethod.Get, "/api/v3/configure/database?format=json");
    req.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token);
    using var resp = await http.SendAsync(req);

    if (resp.StatusCode is HttpStatusCode.Unauthorized or HttpStatusCode.Forbidden)
        throw new InvalidOperationException(
            $"Token can't list databases (HTTP {(int)resp.StatusCode}). Confirm '{database}' exists with: " +
            "influxdb3 show databases --token <admin-token>");
    resp.EnsureSuccessStatusCode();

    using var doc = JsonDocument.Parse(await resp.Content.ReadAsStringAsync());
    var exists = doc.RootElement.EnumerateArray()
        .Any(el => el.GetProperty("iox::database").GetString() == database);
    if (!exists)
        throw new InvalidOperationException(
            $"Database '{database}' not found. Create it first: influxdb3 create database {database} --token <admin-token> " +
            "(writing anyway would silently auto-create a new, possibly misspelled database).");
}

static string Require(string k) =>
    Environment.GetEnvironmentVariable(k) ?? throw new InvalidOperationException($"missing env {k}");
```

## Why it's built this way

- **Batching:** One write per point is the main thing that slows bulk loads. The 1M points go out as 100 requests of 10,000 points each.
- **Unique timestamps:** Points with the same table, tags and timestamp overwrite each other. Each host gets one point per second here, so all 1M points survive at second precision. With real data that has more than one point per second per series, switch to `WritePrecision.Ms` or finer.
- **One invalid line rejects the whole batch:** `InfluxDB3.Client` 1.9.0+ writes through `/api/v2/write` by default, where a single bad line fails the entire 10,000-point batch. On Core or Enterprise, setting the `UseV2Api` write option to `false` switches to `/api/v3/write_lp`. That endpoint accepts partial writes, and after a 400 you resend only the rejected lines.
- **Retries:** 429, 5xx and connection failures get backoff with jitter. Other 4xx errors mean something needs fixing (a bad line, the token, or a missing database), so the run stops.
- **Database listing on Enterprise:** A read/write-scoped token may not be allowed to list databases. In that case the startup check stops with a message telling you to confirm the database with the CLI and an admin token.

